            while x > 0:
                rev = rev * 10 + (x % 10)
                x //= 10
            return rev

        last_seen = {}
        min_dist = float('inf')

        for j, val in enumerate(nums):
            # Check if nums[j] matches reverse(nums[i]) from an earlier index i
            if val in last_seen:
                dist = j - last_seen[val]
                if dist < min_dist:
                    min_dist = dist
                    if min_dist == 1:
                        return 1

            # Record reverse(nums[j]) with its current index j
            rev = reverse(val)
            if rev <= 10**9:
                last_seen[rev] = j

        return -1 if min_dist == float('inf') else min_dist

